import * as THREE from 'three';
import {createLaserModel} from './laser-model.js';
import {createLaserSession,fitLaserCamera} from './laser-session.js';
export const LASER_BODY=`<div class="gym-layout"><div class="gym-court laser-court" id="laser-court" role="img" aria-label="원래 도름이의 두 손과 장난감 빛 도구, 움직이는 원과 별 표적이 보이는 연습장. 끌어서 조준해요" tabindex="0"></div><section class="gym-panel laser-panel" id="laser-panel"><p id="laser-status" role="status"></p><div class="gym-actions"><button id="laser-start">다섯 번 연습 시작</button><button id="laser-pause">잠깐 쉬기</button><button id="laser-exit">멈추고 나오기</button></div><label>좌우 조준 <input id="laser-yaw" type="range" min="-0.16" max="0.16" step="0.005" value="0.025"></label><label>위아래 조준 <input id="laser-pitch" type="range" min="-0.04" max="0.22" step="0.005" value="0.035"></label><div class="gym-hold"><button id="laser-steady" aria-pressed="false">누르는 동안 조준 안정</button><button id="laser-trigger">빛 한 번 보내기</button></div><p id="laser-cooldown"></p><p id="laser-score" role="status"></p><details id="laser-help"><summary>조작 안내</summary><p>화면을 끌거나 슬라이더, 키보드 방향키로 조준해요. 빛 보내기 버튼이나 스페이스를 한 번 누르면 쏴요. 다시 쏘려면 잠깐 기다려요.</p><p>조준 안정 버튼을 누르거나 Shift를 누르는 동안 손 떨림이 줄어요. 길게 누르기 어렵다면 버튼에 초점을 맞추고 Enter로 안정 도움을 켜고 끌 수 있어요. 표적을 자동으로 따라가지는 않아요.</p><p>사람이나 동물이 아닌 움직이는 원과 별에 빛을 보내요. 실제 도구 끝에서 나온 빛이 먼저 닿은 표적만 세어요. 혼자 다섯 번 연습하며 보상이나 저장 기록은 없어요. 화면을 벗어나면 계속하기를 눌러야 이어져요.</p></details></section></div>`;
export function createLaserController({ui,getView,getActors,stage,isAllowed=()=>true,onChange=()=>{},clearInput=()=>{},doc=globalThis.document,win=globalThis.window,sessionFactory=createLaserSession,modelFactory=createLaserModel,fitCamera=fitLaserCamera}){
 const camera=new THREE.OrthographicCamera(),$=id=>doc.querySelector('#'+id);let live=null,pending=false,generation=0;
 function listen(node,type,fn,opts){if(!node)return;node.addEventListener(type,fn,opts);live.listeners.push([node,type,fn,opts]);}
 function clear(){clearInput();if(!live)return;live.pointers.clear();live.steadyPointers.clear();live.keys.clear();live.drag=null;live.assist=false;live.model.setInput({cancel:true});}
 function controls(){if(!live)return;live.model.setInput({steady:live.assist||live.steadyPointers.size>0||live.keys.has('ShiftLeft')||live.keys.has('ShiftRight'),aimX:Number(live.keys.has('ArrowRight'))-Number(live.keys.has('ArrowLeft')),aimY:Number(live.keys.has('ArrowUp'))-Number(live.keys.has('ArrowDown'))});}
 function render(){if(!live)return;const s=live.model.snapshot(),p=live.session.phase,paused=live.suspended||s.paused,ready=live.session.ready&&['idle','ready','stopped'].includes(s.state),active=s.state==='active'&&!paused&&!live.exiting;$('laser-status').textContent=paused?'멈췄어요. 계속하기를 누르면 이어져요':p==='boarding'?'빛 표적 자리로 걸어가요':p==='guarding'?'두 발을 딛고 빛 도구를 준비해요':p==='lowering'||p==='exiting'?'도구를 내리고 천천히 걸어 나와요':live.exiting?'빛이 사라진 뒤 나와요':ready?'준비됐어요. 시작은 직접 골라요':'움직이는 원과 별을 천천히 조준해 보세요';$('laser-score').textContent=`${s.shots} / 5번 · 표적 ${s.hits}번 · 빗나감 ${s.shots-s.hits}번`;$('laser-cooldown').textContent=s.state==='stopped'?'이번 연습을 마쳤어요':s.cooldown>0?`다음 빛까지 ${s.cooldown.toFixed(1)}초`:'준비되면 빛을 한 번 보내요';$('laser-start').disabled=!ready||paused||live.exiting;$('laser-start').textContent=s.state==='stopped'?'다섯 번 다시 연습':'다섯 번 연습 시작';$('laser-pause').textContent=paused?'계속하기':'잠깐 쉬기';$('laser-exit').disabled=live.exiting;$('laser-trigger').disabled=!active||s.cooldown>0;$('laser-steady').disabled=!active;$('laser-steady').setAttribute('aria-pressed',String(s.steady));for(const[id,k]of[['laser-yaw','aimYaw'],['laser-pitch','aimPitch']]){$(id).disabled=!active;$(id).value=String(s[k]);}}
 function clean({restore}={}){pending=false;generation++;if(!live)return;const old=live;live=null;old.observer?.disconnect();for(const[n,t,f,o]of old.listeners)n.removeEventListener(t,f,o);old.model.dispose?.();old.session.dispose({restore:restore??(getView()===old.source)});stage.classList.remove('gym-open');doc.body?.classList.remove('gym-open');clearInput();onChange();}
 function cancel(){const owned=!!live||pending;clean();if(owned)ui.close();}
 function close(){if(!live||live.exiting)return;clear();live.suspended=false;live.model.resume();live.exiting=true;live.model.stop('exit');live.session.requestExit();render();}
 function pause(){if(!live)return;clear();live.suspended=true;live.model.pause();live.session.pause?.();render();}
 function open(){if(live||pending||!isAllowed())return false;const source=getView();if(!source?.schoolView?.gymView?.laser)return false;pending=true;const token=++generation;
 const accepted=ui.workshop('빛 표적 · 혼자 다섯 번 연습',LASER_BODY,()=>{if(token!==generation||!pending)return;if(getView()!==source){pending=false;return;}pending=false;let session;try{session=sessionFactory({view:source,...getActors()});live={session,model:modelFactory(),source,listeners:[],pointers:new Set(),steadyPointers:new Set(),keys:new Set(),assist:false,suspended:false,exiting:false,fit:''};stage.classList.add('gym-open');doc.body?.classList.add('gym-open');clearInput();onChange();
  const act=(id,fn)=>listen($(id),'click',e=>{if(token!==generation||!live||$(id).disabled)return;if(e.detail>0&&live.cancelledPointer)return;e.preventDefault();fn();});
  act('laser-start',()=>{clear();if(live.session.ready)live.model.start();render();});act('laser-exit',close);act('laser-pause',()=>{if(doc.hidden)return;if(live.suspended||live.model.snapshot().paused){clear();live.suspended=false;live.model.resume();render();}else pause();});
  for(const [id,key]of[['laser-yaw','yaw'],['laser-pitch','pitch']])listen($(id),'input',()=>{if(!live||$(id).disabled)return;live.model.setInput({[key]:Number($(id).value)});render();});
  const steady=$('laser-steady'),court=$('laser-court'),canAim=()=>live&&!live.exiting&&!live.suspended&&!live.model.snapshot().paused&&live.model.snapshot().state==='active';
  act('laser-trigger',()=>{live.model.setInput({trigger:true});render();});
  listen(court,'pointerdown',e=>{if(!canAim()||e.button!==0||e.isPrimary===false||live.pointers.size)return;e.preventDefault();live.cancelledPointer=false;court.setPointerCapture?.(e.pointerId);live.pointers.add(e.pointerId);const s=live.model.snapshot();live.drag={id:e.pointerId,x:e.clientX??0,y:e.clientY??0,yaw:s.aimYaw,pitch:s.aimPitch};});
  listen(court,'pointermove',e=>{if(!canAim()||live.drag?.id!==e.pointerId)return;const d=live.drag,b=court.getBoundingClientRect();live.model.setInput({yaw:d.yaw+((e.clientX??d.x)-d.x)/Math.max(1,b.width)*.32,pitch:d.pitch-((e.clientY??d.y)-d.y)/Math.max(1,b.height)*.26});render();});
  for(const type of['pointerup','pointercancel','lostpointercapture'])listen(court,type,e=>{if(!live||!live.pointers.has(e.pointerId))return;live.pointers.delete(e.pointerId);live.drag=null;});
  listen(steady,'pointerdown',e=>{if(!canAim()||e.button!==0||e.isPrimary===false)return;e.preventDefault();live.cancelledPointer=false;steady.setPointerCapture?.(e.pointerId);live.steadyPointers.add(e.pointerId);controls();render();});
  for(const type of['pointerup','pointercancel','lostpointercapture'])listen(steady,type,e=>{if(!live||!live.steadyPointers.has(e.pointerId))return;live.steadyPointers.delete(e.pointerId);if(type!=='pointerup')live.cancelledPointer=true;controls();render();});
  listen(steady,'click',e=>{if(!canAim()||steady.disabled||e.detail>0)return;e.preventDefault();live.assist=!live.assist;controls();render();});
  listen(doc,'keydown',e=>{if(!canAim()||e.repeat||e.ctrlKey||e.altKey||e.metaKey||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;const control=e.target?.closest?.('button,a,summary,[role="button"]')??(['BUTTON','A','SUMMARY'].includes(e.target?.tagName)?e.target:null);if(control)return;if(e.code==='Space'){e.preventDefault();live.model.setInput({trigger:true});render();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','ShiftLeft','ShiftRight'].includes(e.code)){e.preventDefault();live.keys.add(e.code);controls();render();}});
  listen(doc,'keyup',e=>{if(live&&live.keys.has(e.code)){e.preventDefault();live.keys.delete(e.code);controls();render();}});
  listen($('laser-panel'),'pointerdown',()=>{if(live)live.cancelledPointer=false;},true);listen($('laser-panel'),'pointercancel',()=>{if(live)live.cancelledPointer=true;},true);
  const modal=$('modal'),exit=modal?.querySelector?.('[data-close]');if(exit)exit.onclick=e=>{e.preventDefault();close();};listen(modal,'cancel',e=>{e.preventDefault();close();});listen(modal,'click',e=>{if(e.target===modal){e.preventDefault();e.stopImmediatePropagation?.();}},true);
  listen(win,'blur',pause);listen(doc,'visibilitychange',()=>{if(doc.hidden)pause();});listen(win,'pagehide',cancel);const resize=()=>{if(live&&token===generation)viewport(stage.clientWidth,stage.clientHeight);};listen(win,'resize',resize);if(win.visualViewport)listen(win.visualViewport,'resize',resize);if(typeof ResizeObserver==='function'){live.observer=new ResizeObserver(resize);live.observer.observe($('laser-court'));}render();resize();$('laser-court').focus();return()=>{if(token===generation)clean();};
 }catch(error){if(live)clean();else session?.dispose();pending=false;ui.close();ui.toast('빛 표적 자리까지 빈 길이 필요해요. 잠깐 뒤 다시 해 주세요');}},{kind:'gym-workshop laser-workshop',closeLabel:'멈추고 나오기'});if(!accepted&&token===generation)pending=false;return accepted;}
 function runtimeFailure(){const restore=!!live&&getView()===live.source;clean({restore});ui.close();ui.toast('빛 표적 연습을 멈췄어요. 잠깐 뒤 다시 해 주세요');}
 function tick(dt){if(!live)return;if(getView()!==live.source){clean({restore:false});ui.close();return;}try{const s=live.model.snapshot();if(!live.suspended&&!s.paused){if(live.session.ready&&s.state==='idle')live.model.ready();live.session.tick(dt,live.model);if(live.session.ready&&live.model.snapshot().state==='idle')live.model.ready();}if(live.session.done){clean();ui.close();return;}render();}catch(error){runtimeFailure();}}
 function viewport(width,height){if(!live)return{x:0,y:0,width,height};const b=$('laser-court').getBoundingClientRect(),a=stage.getBoundingClientRect(),rect={x:Math.max(0,b.left-a.left),y:Math.max(0,b.top-a.top),width:Math.max(1,Math.min(b.width,width)),height:Math.max(1,Math.min(b.height,height))},key=Object.values(rect).join(',')+','+['ready','exercise'].includes(live.session.phase);if(key!==live.fit){try{fitCamera(camera,live.session.root,rect,{active:['ready','exercise'].includes(live.session.phase)});live.fit=key;}catch(error){runtimeFailure();}}return rect;}
 return{open,close,cancel,pause,tick,viewport,camera,dispose:cancel,get active(){return!!live;},snapshot:()=>live?{...live.model.snapshot(),paused:live.suspended||live.model.snapshot().paused,session:live.session.snapshot(),exiting:live.exiting}:null};
}
